import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
# ---------------------------------------------------------------------------
# Hand-authored PTX implementing a CTA-tiled 2D convolution with asymmetric
# kernel, stride, padding and dilation. Each CTA cooperatively stages a
# reusable input tile (per input channel) into shared memory and each thread
# computes one output element (n, oc, oh, ow) within the CTA's spatial tile,
# reusing the staged input tile across all kernel taps and across all
# threads in the tile (instead of each thread independently re-reading
# global memory for every kernel tap). Register-blocked over 8 output
# channels per CTA (OC_TILE=8) so each staged shared-memory input value is
# reused for 8 FMAs instead of 4, further improving the compute-to-shared-
# load ratio without adding extra shared-memory input traffic.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64
.visible .entry conv2d_kernel(
    .param .u64 conv2d_kernel_param_0,
    .param .u64 conv2d_kernel_param_1,
    .param .u64 conv2d_kernel_param_2,
    .param .u64 conv2d_kernel_param_3,
    .param .u32 conv2d_kernel_param_4,
    .param .u32 conv2d_kernel_param_5,
    .param .u32 conv2d_kernel_param_6,
    .param .u32 conv2d_kernel_param_7,
    .param .u32 conv2d_kernel_param_8,
    .param .u32 conv2d_kernel_param_9,
    .param .u32 conv2d_kernel_param_10,
    .param .u32 conv2d_kernel_param_11,
    .param .u32 conv2d_kernel_param_12,
    .param .u32 conv2d_kernel_param_13,
    .param .u32 conv2d_kernel_param_14,
    .param .u32 conv2d_kernel_param_15,
    .param .u32 conv2d_kernel_param_16,
    .param .u32 conv2d_kernel_param_17,
    .param .u32 conv2d_kernel_param_18
)
{
    .reg .pred %p<40>;
    .reg .b32 %r<200>;
    .reg .b64 %rd<120>;
    .reg .f32 %f<32>;
    .shared .align 16 .b8 smem_buf[16384];
    ld.param.u64 %rd1, [conv2d_kernel_param_0];   // x_ptr
    ld.param.u64 %rd2, [conv2d_kernel_param_1];   // w_ptr
    ld.param.u64 %rd3, [conv2d_kernel_param_2];   // bias_ptr
    ld.param.u64 %rd4, [conv2d_kernel_param_3];   // y_ptr
    ld.param.u32 %r5,  [conv2d_kernel_param_4];   // N
    ld.param.u32 %r6,  [conv2d_kernel_param_5];   // Cin
    ld.param.u32 %r7,  [conv2d_kernel_param_6];   // H
    ld.param.u32 %r8,  [conv2d_kernel_param_7];   // W
    ld.param.u32 %r9,  [conv2d_kernel_param_8];   // Cout
    ld.param.u32 %r10, [conv2d_kernel_param_9];   // Kh
    ld.param.u32 %r11, [conv2d_kernel_param_10];  // Kw
    ld.param.u32 %r12, [conv2d_kernel_param_11];  // stride
    ld.param.u32 %r13, [conv2d_kernel_param_12];  // pad_h
    ld.param.u32 %r14, [conv2d_kernel_param_13];  // pad_w
    ld.param.u32 %r15, [conv2d_kernel_param_14];  // dil_h
    ld.param.u32 %r16, [conv2d_kernel_param_15];  // dil_w
    ld.param.u32 %r17, [conv2d_kernel_param_16];  // Hout
    ld.param.u32 %r18, [conv2d_kernel_param_17];  // Wout
    ld.param.u32 %r19, [conv2d_kernel_param_18];  // has_bias
    cvta.to.global.u64 %rd5, %rd1;   // X global
    cvta.to.global.u64 %rd6, %rd2;   // W global
    cvta.to.global.u64 %rd7, %rd4;   // Y global
    mov.u32 %r20, %tid.x;    // tx  (0..31, TILE_W)
    mov.u32 %r21, %tid.y;    // ty  (0..7,  TILE_H)
    mov.u32 %r22, %ctaid.x;  // bx
    mov.u32 %r23, %ctaid.y;  // by
    mov.u32 %r24, %ctaid.z;  // bz  (n*num_oc_groups+ocg), OC_TILE=8 (register blocked)
    add.s32 %r100, %r9, 7;        // Cout+7
    shr.u32 %r101, %r100, 3;      // num_oc_groups = ceil(Cout/8)
    div.u32 %r25, %r24, %r101;    // n
    rem.u32 %r102, %r24, %r101;   // ocg
    mul.lo.s32 %r26, %r102, 8;    // oc0
    add.s32 %r103, %r26, 1;       // oc1
    add.s32 %r104, %r26, 2;       // oc2
    add.s32 %r105, %r26, 3;       // oc3
    add.s32 %r114, %r26, 4;       // oc4
    add.s32 %r115, %r26, 5;       // oc5
    add.s32 %r116, %r26, 6;       // oc6
    add.s32 %r117, %r26, 7;       // oc7
    setp.lt.s32 %p24, %r103, %r9; // valid_oc1
    setp.lt.s32 %p25, %r104, %r9; // valid_oc2
    setp.lt.s32 %p26, %r105, %r9; // valid_oc3
    setp.lt.s32 %p27, %r114, %r9; // valid_oc4
    setp.lt.s32 %p28, %r115, %r9; // valid_oc5
    setp.lt.s32 %p29, %r116, %r9; // valid_oc6
    setp.lt.s32 %p30, %r117, %r9; // valid_oc7
    sub.s32 %r106, %r9, 1;        // Cout-1
    min.s32 %r107, %r103, %r106;  // oc1 clamped for safe addressing
    min.s32 %r108, %r104, %r106;  // oc2 clamped for safe addressing
    min.s32 %r109, %r105, %r106;  // oc3 clamped for safe addressing
    min.s32 %r118, %r114, %r106;  // oc4 clamped for safe addressing
    min.s32 %r119, %r115, %r106;  // oc5 clamped for safe addressing
    min.s32 %r120, %r116, %r106;  // oc6 clamped for safe addressing
    min.s32 %r121, %r117, %r106;  // oc7 clamped for safe addressing
    mul.lo.s32 %r27, %r23, 8;      // by*TILE_H
    add.s32 %r28, %r27, %r21;      // oh
    mul.lo.s32 %r29, %r22, 32;     // bx*TILE_W
    add.s32 %r30, %r29, %r20;      // ow
    mul.lo.s32 %r31, %r27, %r12;   // by*TILE_H*stride
    sub.s32 %r32, %r31, %r13;      // ih_base
    mul.lo.s32 %r33, %r29, %r12;   // bx*TILE_W*stride
    sub.s32 %r34, %r33, %r14;      // iw_base
    sub.s32 %r35, %r10, 1;         // Kh-1
    mul.lo.s32 %r36, %r15, %r35;   // dil_h*(Kh-1)
    mul.lo.s32 %r37, %r12, 7;      // stride*(TILE_H-1)
    add.s32 %r38, %r36, %r37;
    add.s32 %r39, %r38, 1;         // patch_h
    sub.s32 %r40, %r11, 1;         // Kw-1
    mul.lo.s32 %r41, %r16, %r40;   // dil_w*(Kw-1)
    mul.lo.s32 %r42, %r12, 31;     // stride*(TILE_W-1)
    add.s32 %r43, %r41, %r42;
    add.s32 %r44, %r43, 1;         // patch_w
    mul.lo.s32 %r45, %r39, %r44;   // patch_size
    mul.lo.s32 %r46, %r21, 32;
    add.s32 %r47, %r46, %r20;      // flat_tid (0..255)
    mul.lo.s32 %r90, %r21, %r12;   // ty*stride
    mul.lo.s32 %r91, %r20, %r12;   // tx*stride
    sub.s32 %r92, %r7, 1;          // H-1
    sub.s32 %r93, %r8, 1;          // W-1
    mov.u32 %r49, smem_buf;        // shared memory base address
    mul.lo.s32 %r131, %r45, 4;     // patch_size*4 (patch bytes)
    add.s32 %r134, %r131, 15;
    and.b32  %r135, %r134, 0xfffffff0;    // round up to 16B for aligned vectorized weight loads
    add.s32 %r130, %r49, %r135;    // wt_smem_base = smem_buf + padded patch_bytes (16B aligned)
    mul.lo.s32 %r132, %r10, %r11;  // KhKw = Kh*Kw
    mul.lo.s32 %r133, %r132, 8;    // n_wt = KhKw*8 (OC_TILE=8)
    setp.lt.s32 %p20, %r28, %r17;  // oh < Hout
    setp.lt.s32 %p21, %r30, %r18;  // ow < Wout
    and.pred %p22, %p20, %p21;     // valid_out
    mov.f32 %f10, 0f00000000;      // acc oc0
    mov.f32 %f11, 0f00000000;      // acc oc1
    mov.f32 %f12, 0f00000000;      // acc oc2
    mov.f32 %f13, 0f00000000;      // acc oc3
    mov.f32 %f14, 0f00000000;      // acc oc4
    mov.f32 %f15, 0f00000000;      // acc oc5
    mov.f32 %f16, 0f00000000;      // acc oc6
    mov.f32 %f17, 0f00000000;      // acc oc7
    setp.eq.u32 %p23, %r19, 0;
    @%p23 bra SKIP_BIAS;
    cvta.to.global.u64 %rd8, %rd3;
    mul.wide.s32 %rd9, %r26, 4;
    add.s64 %rd10, %rd8, %rd9;
    ld.global.f32 %f10, [%rd10];
    mul.wide.s32 %rd46, %r107, 4;
    add.s64 %rd47, %rd8, %rd46;
    ld.global.f32 %f20, [%rd47];
    selp.f32 %f11, %f20, 0f00000000, %p24;
    mul.wide.s32 %rd48, %r108, 4;
    add.s64 %rd49, %rd8, %rd48;
    ld.global.f32 %f21, [%rd49];
    selp.f32 %f12, %f21, 0f00000000, %p25;
    mul.wide.s32 %rd50, %r109, 4;
    add.s64 %rd51, %rd8, %rd50;
    ld.global.f32 %f22, [%rd51];
    selp.f32 %f13, %f22, 0f00000000, %p26;
    mul.wide.s32 %rd52, %r118, 4;
    add.s64 %rd53, %rd8, %rd52;
    ld.global.f32 %f23, [%rd53];
    selp.f32 %f14, %f23, 0f00000000, %p27;
    mul.wide.s32 %rd54, %r119, 4;
    add.s64 %rd55, %rd8, %rd54;
    ld.global.f32 %f24, [%rd55];
    selp.f32 %f15, %f24, 0f00000000, %p28;
    mul.wide.s32 %rd56, %r120, 4;
    add.s64 %rd57, %rd8, %rd56;
    ld.global.f32 %f25, [%rd57];
    selp.f32 %f16, %f25, 0f00000000, %p29;
    mul.wide.s32 %rd58, %r121, 4;
    add.s64 %rd59, %rd8, %rd58;
    ld.global.f32 %f26, [%rd59];
    selp.f32 %f17, %f26, 0f00000000, %p30;
SKIP_BIAS:
    cvt.s64.s32 %rd11, %r25;      // n
    cvt.s64.s32 %rd12, %r6;       // Cin
    cvt.s64.s32 %rd13, %r7;       // H
    cvt.s64.s32 %rd14, %r8;       // W
    cvt.s64.s32 %rd15, %r10;      // Kh
    cvt.s64.s32 %rd16, %r11;      // Kw
    mul.lo.s64 %rd17, %rd13, %rd14;   // sXc = H*W
    mul.lo.s64 %rd18, %rd12, %rd17;   // sXn = Cin*H*W
    mul.lo.s64 %rd19, %rd11, %rd18;   // xn_off = n*sXn
    mul.lo.s64 %rd20, %rd15, %rd16;   // sWc = Kh*Kw
    mul.lo.s64 %rd21, %rd12, %rd20;   // sWo = Cin*Kh*Kw
    mov.u32 %r50, 0;               // ci
LOOP_CI:
    setp.ge.s32 %p1, %r50, %r6;
    @%p1 bra END_CI;
    cvt.s64.s32 %rd24, %r50;
    mul.lo.s64 %rd25, %rd24, %rd17;   // ci*sXc
    add.s64 %rd26, %rd19, %rd25;      // xc_off
    mul.lo.s64 %rd27, %rd24, %rd20;   // ci*sWc
    // -------- cooperative load of the reusable input tile --------
    mov.u32 %r51, %r47;            // idx = flat_tid
LOOP_LOAD:
    setp.ge.s32 %p2, %r51, %r45;
    @%p2 bra END_LOAD;
    div.u32 %r52, %r51, %r44;      // r = idx / patch_w
    rem.u32 %r53, %r51, %r44;      // c = idx % patch_w
    add.s32 %r54, %r32, %r52;      // ih = ih_base + r
    add.s32 %r55, %r34, %r53;      // iw = iw_base + c
    setp.ge.s32 %p3, %r54, 0;
    setp.lt.s32 %p4, %r54, %r7;
    and.pred %p5, %p3, %p4;
    setp.ge.s32 %p6, %r55, 0;
    setp.lt.s32 %p7, %r55, %r8;
    and.pred %p8, %p6, %p7;
    and.pred %p9, %p5, %p8;        // valid_load
    max.s32 %r56, %r54, 0;
    min.s32 %r57, %r56, %r92;      // clamped ih
    max.s32 %r58, %r55, 0;
    min.s32 %r59, %r58, %r93;      // clamped iw
    cvt.s64.s32 %rd29, %r57;
    mul.lo.s64 %rd30, %rd29, %rd14;   // ih*W
    add.s64 %rd31, %rd26, %rd30;      // xc_off + ih*W
    cvt.s64.s32 %rd32, %r59;
    add.s64 %rd33, %rd31, %rd32;      // x_off
    mul.lo.s64 %rd34, %rd33, 4;
    add.s64 %rd35, %rd5, %rd34;
    ld.global.f32 %f2, [%rd35];
    selp.f32 %f3, %f2, 0f00000000, %p9;
    mul.lo.s32 %r60, %r51, 4;
    add.s32 %r61, %r49, %r60;
    st.shared.f32 [%r61], %f3;
    add.s32 %r51, %r51, 256;
    bra.uni LOOP_LOAD;
END_LOAD:
    mov.u32 %r140, %r47;            // idx2 = flat_tid
LOOP_WLOAD:
    setp.ge.s32 %p31, %r140, %r133;
    @%p31 bra END_WLOAD;
    div.u32 %r141, %r140, %r132;    // oc_sel = idx2 / KhKw
    rem.u32 %r142, %r140, %r132;    // koff = idx2 % KhKw
    add.s32 %r180, %r26, %r141;     // oc0 + oc_sel
    min.s32 %r181, %r180, %r106;    // clamp to Cout-1 -> oc_k (safe addressing)
    cvt.s64.s32 %rd100, %r181;
    mul.lo.s64 %rd101, %rd100, %rd21;   // oc_k * sWo
    add.s64 %rd102, %rd101, %rd27;      // + ci*sWc
    cvt.s64.s32 %rd103, %r142;
    add.s64 %rd104, %rd102, %rd103;     // + koff -> element offset
    mul.lo.s64 %rd105, %rd104, 4;
    add.s64 %rd106, %rd6, %rd105;       // global weight address
    ld.global.f32 %f29, [%rd106];
    mul.lo.s32 %r143, %r142, 32;    // koff*32
    mul.lo.s32 %r145, %r141, 4;     // oc_sel*4
    add.s32 %r146, %r143, %r145;
    add.s32 %r144, %r130, %r146;    // wt smem addr (layout: [koff][oc_sel], OC_TILE=8 contiguous)
    st.shared.f32 [%r144], %f29;
    add.s32 %r140, %r140, 256;
    bra.uni LOOP_WLOAD;
END_WLOAD:
    bar.sync 0;
    @!%p22 bra SKIP_COMPUTE;
    mov.u32 %r70, 0;               // kh
LOOP_KH2:
    setp.ge.s32 %p10, %r70, %r10;
    @%p10 bra END_KH2;
    mul.lo.s32 %r72, %r70, %r15;   // kh*dil_h
    add.s32 %r73, %r90, %r72;      // shared row = ty*stride + kh*dil_h
    mul.lo.s32 %r74, %r73, %r44;   // row*patch_w
    add.s32 %r77, %r74, %r91;      // smem_idx at kw=0 (row*patch_w + tx*stride)
    mul.lo.s32 %r79, %r77, 4;
    add.s32 %r80, %r49, %r79;      // smem byte addr at kw=0
    mul.lo.s32 %r110, %r16, 4;     // dil_w*4 (smem col byte stride per kw step)
    mul.lo.s32 %r81, %r70, %r11;   // kh*Kw
    mul.lo.s32 %r160, %r81, 32;    // kh*Kw*32 (wt row byte offset; OC_TILE=8 contiguous per koff)
    add.s32 %r161, %r130, %r160;   // wt smem addr at kw=0 (8 contiguous floats: oc0..oc7)
    mov.u32 %r75, 0;               // kw
LOOP_KW2:
    setp.ge.s32 %p11, %r75, %r11;
    @%p11 bra END_KW2;
    ld.shared.f32 %f5, [%r80];
    ld.shared.v4.f32 {%f6, %f7, %f8, %f9}, [%r161];
    add.s32 %r162, %r161, 16;
    ld.shared.v4.f32 {%f18, %f19, %f27, %f28}, [%r162];
    fma.rn.f32 %f10, %f5, %f6, %f10;
    fma.rn.f32 %f11, %f5, %f7, %f11;
    fma.rn.f32 %f12, %f5, %f8, %f12;
    fma.rn.f32 %f13, %f5, %f9, %f13;
    fma.rn.f32 %f14, %f5, %f18, %f14;
    fma.rn.f32 %f15, %f5, %f19, %f15;
    fma.rn.f32 %f16, %f5, %f27, %f16;
    fma.rn.f32 %f17, %f5, %f28, %f17;
    add.s32 %r80, %r80, %r110;
    add.s32 %r161, %r161, 32;
    add.s32 %r75, %r75, 1;
    bra.uni LOOP_KW2;
END_KW2:
    add.s32 %r70, %r70, 1;
    bra.uni LOOP_KH2;
END_KH2:
SKIP_COMPUTE:
    bar.sync 0;
    add.s32 %r50, %r50, 1;
    bra.uni LOOP_CI;
END_CI:
    @!%p22 bra DONE;
    // y_off0 = ((n*Cout+oc0)*Hout+oh)*Wout+ow
    mul.lo.s32 %r95, %r25, %r9;
    add.s32 %r95, %r95, %r26;
    mul.lo.s32 %r95, %r95, %r17;
    add.s32 %r95, %r95, %r28;
    mul.lo.s32 %r95, %r95, %r18;
    add.s32 %r95, %r95, %r30;
    cvt.s64.s32 %rd43, %r95;
    mul.lo.s64 %rd44, %rd43, 4;
    add.s64 %rd45, %rd7, %rd44;
    st.global.f32 [%rd45], %f10;
    @!%p24 bra DONE;
    // y_off1 = ((n*Cout+oc1)*Hout+oh)*Wout+ow
    mul.lo.s32 %r111, %r25, %r9;
    add.s32 %r111, %r111, %r103;
    mul.lo.s32 %r111, %r111, %r17;
    add.s32 %r111, %r111, %r28;
    mul.lo.s32 %r111, %r111, %r18;
    add.s32 %r111, %r111, %r30;
    cvt.s64.s32 %rd73, %r111;
    mul.lo.s64 %rd74, %rd73, 4;
    add.s64 %rd75, %rd7, %rd74;
    st.global.f32 [%rd75], %f11;
    @!%p25 bra DONE;
    // y_off2 = ((n*Cout+oc2)*Hout+oh)*Wout+ow
    mul.lo.s32 %r112, %r25, %r9;
    add.s32 %r112, %r112, %r104;
    mul.lo.s32 %r112, %r112, %r17;
    add.s32 %r112, %r112, %r28;
    mul.lo.s32 %r112, %r112, %r18;
    add.s32 %r112, %r112, %r30;
    cvt.s64.s32 %rd76, %r112;
    mul.lo.s64 %rd77, %rd76, 4;
    add.s64 %rd78, %rd7, %rd77;
    st.global.f32 [%rd78], %f12;
    @!%p26 bra DONE;
    // y_off3 = ((n*Cout+oc3)*Hout+oh)*Wout+ow
    mul.lo.s32 %r113, %r25, %r9;
    add.s32 %r113, %r113, %r105;
    mul.lo.s32 %r113, %r113, %r17;
    add.s32 %r113, %r113, %r28;
    mul.lo.s32 %r113, %r113, %r18;
    add.s32 %r113, %r113, %r30;
    cvt.s64.s32 %rd79, %r113;
    mul.lo.s64 %rd80, %rd79, 4;
    add.s64 %rd81, %rd7, %rd80;
    st.global.f32 [%rd81], %f13;
    @!%p27 bra DONE;
    // y_off4 = ((n*Cout+oc4)*Hout+oh)*Wout+ow
    mul.lo.s32 %r122, %r25, %r9;
    add.s32 %r122, %r122, %r114;
    mul.lo.s32 %r122, %r122, %r17;
    add.s32 %r122, %r122, %r28;
    mul.lo.s32 %r122, %r122, %r18;
    add.s32 %r122, %r122, %r30;
    cvt.s64.s32 %rd82, %r122;
    mul.lo.s64 %rd83, %rd82, 4;
    add.s64 %rd84, %rd7, %rd83;
    st.global.f32 [%rd84], %f14;
    @!%p28 bra DONE;
    // y_off5 = ((n*Cout+oc5)*Hout+oh)*Wout+ow
    mul.lo.s32 %r123, %r25, %r9;
    add.s32 %r123, %r123, %r115;
    mul.lo.s32 %r123, %r123, %r17;
    add.s32 %r123, %r123, %r28;
    mul.lo.s32 %r123, %r123, %r18;
    add.s32 %r123, %r123, %r30;
    cvt.s64.s32 %rd85, %r123;
    mul.lo.s64 %rd86, %rd85, 4;
    add.s64 %rd87, %rd7, %rd86;
    st.global.f32 [%rd87], %f15;
    @!%p29 bra DONE;
    // y_off6 = ((n*Cout+oc6)*Hout+oh)*Wout+ow
    mul.lo.s32 %r124, %r25, %r9;
    add.s32 %r124, %r124, %r116;
    mul.lo.s32 %r124, %r124, %r17;
    add.s32 %r124, %r124, %r28;
    mul.lo.s32 %r124, %r124, %r18;
    add.s32 %r124, %r124, %r30;
    cvt.s64.s32 %rd88, %r124;
    mul.lo.s64 %rd89, %rd88, 4;
